insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 165, 'ആദ്യമായി വസ്ത്രം ധരിപ്പിക്കപ്പെടുന്നവൻ', null, 897 from books where volume_id=1 and book_no=31 on conflict (book_id, chapter_no) do nothing;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: نُهينَا أَنْ نَسْأَلَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ شَيْءٍ، فَكَانَ يُعْجِبُنَا أَنْ يَجِيءَ الرَّجُلُ – مِنْ أَهْلِ الْبَادِيَةِ – الْعَاقِلُ فَيَسْأَلَهُ وَنَحْنُ نَسْمَعُ، فَجَاءَ رَجُلٌ مِنْ أَهْلِ الْبَادِيَةِ فَقَالَ: يَا مُحَمَّدُ! أَتَانَا رَسُولُكَ، فَزَعَمَ لَنَا أَنَّكَ تَزْعُمُ أَنَّ اللهَ أَرْسَلَكَ؟ قَالَ: "صَدَقَ". قَالَ: فَمَنْ خَلَقَ السَّمَاءَ؟ قَالَ: "اللهُ". قَالَ: فَمَنْ خَلَقَ الْأَرْضَ؟ قَالَ: "اللهُ". قَالَ: فَمَنْ نَصَبَ هَذِهِ الْجِبَالَ وَجَعَلَ فِيهَا مَا جَعَلَ؟ قَالَ: "اللهُ". قَالَ: فَبِالَّذِي خَلَقَ السَّمَاءَ وَخَلَقَ الْأَرْضَ وَنَصَبَ هَذِهِ الْجِبَالَ، آللهُ أَرْسَلَكَ؟ قَالَ: "نَعَمْ". قَالَ: وَزَعَمَ رَسُولُكَ أَنَّ عَلَيْنَا خَمْسَ صَلَوَاتٍ فِي يَوْمِنَا وَلَيْلَتِنَا؟ قَالَ: "صَدَقَ". قَالَ: فَبِالَّذِي أَرْسَلَكَ! آللهُ أَمَرَكَ بِهَذَا؟ قَالَ: "نَعَمْ". قَالَ: وَزَعَمَ رَسُولُكَ أَنَّ عَلَيْنَا زَكَاةً فِي أَمْوَالِنَا؟ قَالَ: "صَدَقَ". قَالَ: فَبِالَّذِي أَرْسَلَكَ! آللهُ أَمَرَكَ بِهَذَا؟ قَالَ: "نَعَمْ". قَالَ: وَزَعَمَ رَسُولُكَ أَنَّ عَلَيْنَا صَوْمَ شَهْرِ رَمَضَانَ فِي سَنَتِنَا؟ قَالَ: "صَدَقَ". قَالَ: فَبِالَّذِي أَرْسَلَكَ! آللهُ أَمَرَكَ بِهَذَا؟ قَالَ: "نَعَمْ". قَالَ: وَزَعَمَ رَسُولُكَ أَنَّ عَلَيْنَا حَجَّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا؟ قَالَ: "صَدَقَ". قَالَ: ثُمَّ وَلَّى قَالَ: وَالَّذِي بَعَثَكَ بِالْحَقِّ! لَا أَزِيدُ عَلَيْهِنَّ وَلَا أَنْقُصُ مِنْهُنَّ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَئِنْ صَدَقَ لَيَدْخُلَنَّ الْجَنَّةَ". (م,جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ)യോട് ഏതെങ്കിലും കാര്യത്തെക്കുറിച്ച് ചോദിക്കുന്നതു ഞങ്ങൾക്ക് നിരോധിക്കപ്പെട്ടിരുന്നു. അതു കാരണത്താൽ ഗ്രാമീണനായ, ബുദ്ധിമാനായ ഏതെങ്കിലും ഒരാൾ ഞങ്ങൾ കേൾക്കേ നബി(സ)യോട് വല്ലതും ചോദിക്കുന്നത് ഞങ്ങൾക്ക് സന്തോഷമായിരുന്നു. അങ്ങനെയിരിക്കെ ഗ്രാമീണനായ ഒരാൾ വന്ന് നബി(സ)യോട് ചോദിച്ചു: മുഹമ്മദ്! അല്ലാഹു നിയോഗിച്ച ദൂതനാണെന്ന് താങ്കൾ അവകാശപ്പെടുന്നുണ്ടെന്ന് നിന്റെ ദൂതൻ ഞങ്ങളുടെ അടുത്തുവന്നു പറയുന്നു. നബി(സ) പറഞ്ഞു: "അദ്ദേഹം പറഞ്ഞത് സത്യമാണ്." അയാൾ ചോദിച്ചു: ആരാണ് ആകാശം സൃഷ്ടിച്ചത്? നബി(സ) പറഞ്ഞു: "അല്ലാഹു." അയാൾ ചോദിച്ചു: ആരാണ് ഭൂമിയെ സൃഷ്ടിച്ചത്?. നബി(സ) പറഞ്ഞു: "അല്ലാഹു." ആരാണ് പർവ്വതങ്ങൾ നാട്ടി നിർത്തിയതും അവയിൽ പലതും സൃഷ്ടിച്ചതും? തിരുമേനി(സ) പറഞ്ഞു: "അല്ലാഹു." അയാൾ പറഞ്ഞു: ആകാശഭൂമികളെ സൃഷ്ടിക്കുകയും പർവ്വതം നാട്ടി നിർത്തുകയും ചെയ്തവനാണ! അല്ലാഹുവാണോ താങ്കളെ അയച്ചത്? നബി(സ) പറഞ്ഞു: "അതെ." അയാൾ ചോദിച്ചു: ഞങ്ങൾക്കു രാവിലും പകലിലുമായി അഞ്ച് നിസ്കാരം നിർബന്ധമാണെന്ന് നിങ്ങളുടെ ദൂതൻ പറഞ്ഞുവല്ലോ? നബി(സ) പറഞ്ഞു: "ശരിയാണ്." അപ്പോൾ അയാൾ പറഞ്ഞു: താങ്കളെ അയച്ചവനാണെ! അല്ലാഹുവാണോ താങ്കളോടിത് കൽപിച്ചത്? നബി(സ) പറഞ്ഞു: "അതെ." ഞങ്ങളുടെ ധനത്തിൽ നിർബന്ധദാനമുണ്ടെന്ന് താങ്കളുടെ ദൂതൻ പറഞ്ഞുവല്ലോ? നബി(സ) പറഞ്ഞു: "ശരിയാണ്." അപ്പോൾ അയാൾ പറഞ്ഞു: താങ്കളെ അയച്ചവനാണ! അല്ലാഹുവാണോ താങ്കളോടിത് കൽപിച്ചത്? നബി(സ) പറഞ്ഞു: "അതെ." വർഷത്തിൽ റമദാൻ മാസം വ്രതമനുഷ്ഠിക്കണമെന്ന് താങ്കളുടെ ദൂതൻ പറയുന്നുവല്ലോ? നബി(സ) പറഞ്ഞു: "സത്യമാണ്." അയാൾ പറഞ്ഞു: അല്ലാഹുവാണോ ഇത് കൽപിച്ചത്? നബി(സ) പറഞ്ഞു: "അതെ." അദ്ദേഹം പറഞ്ഞു: സാധിക്കുന്നവർക്ക് ഹജ്ജ് നിർബന്ധമാണെന്ന് താങ്കളുടെ ദൂതൻ പറയുന്നുവല്ലോ? നബി(സ) പറഞ്ഞു: "സത്യമാണ്." പിന്നെ അയാൾ ഇപ്രകാരം പറഞ്ഞുകൊണ്ട് തിരിച്ചുപോയി: താങ്കളെ നിയോഗിച്ചവനാണ! ഞാൻ ഇതിൽ നിന്ന് ഒന്നും കുറക്കുകയോ വർദ്ധിപ്പിക്കുകയോ ഇല്ല. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അയാൾ പറഞ്ഞത് സത്യമെങ്കിൽ തീർച്ചയായും അയാൾ സ്വർഗ്ഗസ്ഥനാകും." (മു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 309, 310, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ أَبُو ذَرٍّ يُحَدِّثُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "فُرِجَ عَنْ سَقْفِ بَيْتِي وَأَنَا بِمَكَّةَ، فَنَزَلَ جِبْرِيلُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَفَرَجَ صَدْرِي، ثُمَّ غَسَلَهُ بِمَاءِ زَمْزَمَ، ثُمَّ جَاءَ بِطَسْتٍ مِنْ ذَهَبٍ مُمْتَلِئٍ حِكْمَةً وَإِيمَانًا، فَأَفْرَغَهُ فِي صَدْرِي، ثُمَّ أَطْبَقَهُ ثُمَّ أَخَذَ بِيَدِي، فَعَرَجَ بِي إِلَى السَّمَاءِ الدُّنْيَا، فَلَمَّا جِئْتُ إِلَى السَّمَاءِ الدُّنْيَا قَالَ جِبْرِيلُ لِخَازِنِ السَّمَاءِ: افْتَحْ، قَالَ: مَنْ هَذَا؟ قَالَ: هَذَا جِبْرِيلُ، قَالَ: هَلْ مَعَكَ أَحَدٌ؟ قَالَ: نَعَمْ، مَعِي مُحَمَّدٌ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: أُرْسِلَ إِلَيْهِ؟ قَالَ: نَعَمْ، فَلَمَّا فَتَحَ عَلَوْنَا السَّمَاءَ الدُّنْيَا، فَإِذَا رَجُلٌ قَاعِدٌ، عَلَى يَمِينِهِ أَسْوِدَةٌ وَعَلَى يَسَارِهِ أَسْوِدَةٌ، إِذَا نَظَرَ قِبَلَ يَمِينِهِ ضَحِكَ، وَإِذَا نَظَرَ قِبَلَ يَسَارِهِ بَكَى، فَقَالَ: مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالِابْنِ الصَّالِحِ، قُلْتُ لِجِبْرِيلَ: مَنْ هَذَا؟ قَالَ: هَذَا آدَمُ، وَهَذِهِ الْأَسْوِدَةُ عَنْ يَمِينِهِ وَشِمَالِهِ نَسَمُ بَنِيهِ، فَأَهْلُ الْيَمِينِ مِنْهُمْ أَهْلُ الْجَنَّةِ، وَالْأَسْوِدَةُ الَّتِي عَنْ شِمَالِهِ أَهْلُ النَّارِ، فَإِذَا نَظَرَ عَنْ يَمِينِهِ ضَحِكَ وَإِذَا نَظَرَ قِبَلَ شِمَالِهِ بَكَى حَتَّى عَرَجَ بِي إِلَى السَّمَاءِ الثَّانِيَةِ، فَقَالَ لِخَازِنِهَا: افْتَحْ، فَقَالَ لَهُ خَازِنُهَا مِثْلَ مَا قَالَ الْأَوَّلُ: فَفَتَحَ، قَالَ أَنَسٌ: فَذَكَرَ أَنَّهُ وَجَدَ فِي السَّمَوَاتِ آدَمَ وَإِدْرِيسَ وَمُوسَى وَعِيسَى وَإِبْرَاهِيمَ صَلَوَاتُ اللهِ عَلَيْهِمْ، وَلَمْ يُثْبِتْ كَيْفَ مَنَازِلُهُمْ غَيْرَ أَنَّهُ ذَكَرَ أَنَّهُ وَجَدَ آدَمَ فِي السَّمَاءِ الدُّنْيَا وَإِبْرَاهِيمَ فِي السَّمَاءِ السَّادِسَةِ، قَالَ أَنَسٌ: فَلَمَّا مَرَّ جِبْرِيلُ بِالنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِإِدْرِيسَ قَالَ: مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالْأَخِ الصَّالِحِ، فَقُلْتُ: مَنْ هَذَا؟ قَالَ: هَذَا إِدْرِيسُ، ثُمَّ مَرَرْتُ بِمُوسَى فَقَالَ: مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالْأَخِ الصَّالِحِ، قُلْتُ: مَنْ هَذَا؟ قَالَ: هَذَا مُوسَى، ثُمَّ مَرَرْتُ بِعِيسَى فَقَالَ: مَرْحَبًا بِالْأَخِ الصَّالِحِ وَالنَّبِيِّ الصَّالِحِ، قُلْتُ: مَنْ هَذَا؟ قَالَ: هَذَا عِيسَى، ثُمَّ مَرَرْتُ بِإِبْرَاهِيمَ فَقَالَ: مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالِابْنِ الصَّالِحِ، قُلْتُ: مَنْ هَذَا؟ قَالَ: هَذَا إِبْرَاهِيمُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، أَنَّ ابْنَ عَبَّاسٍ وَأَبَا حَبَّةَ الْأَنْصَارِيَّ كَانَا يَقُولَانِ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: ثُمَّ عُرِجَ بِي حَتَّى ظَهَرْتُ لِمُسْتَوًى أَسْمَعُ فِيهِ صَرِيفَ الْأَقْلَامِ، قَالَ أَنَسُ بْنُ مَالِكٍ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَفَرَضَ اللهُ عَزَّ وَجَلَّ عَلَى أُمَّتِي خَمْسِينَ صَلَاةً، فَرَجَعْتُ بِذَلِكَ حَتَّى مَرَرْتُ عَلَى مُوسَى فَقَالَ: مَا فَرَضَ اللهُ لَكَ عَلَى أُمَّتِكَ؟ قُلْتُ: فَرَضَ خَمْسِينَ صَلَاةً، قَالَ: فَارْجِعْ إِلَى رَبِّكَ فَإِنَّ أُمَّتَكَ لَا تُطِيقُ ذَلِكَ، فَرَاجَعْتُ فَوَضَعَ شَطْرَهَا، فَرَجَعْتُ إِلَى مُوسَى قُلْتُ: وَضَعَ شَطْرَهَا: فَقَالَ رَاجِعْ رَبَّكَ، فَإِنَّ أُمَّتَكَ لَا تُطِيقُ، فَرَاجَعْتُ فَوَضَعَ شَطْرَهَا، فَرَجَعْتُ إِلَيْهِ فَقَالَ: ارْجِعْ إِلَى رَبِّكَ، فَإِنَّ أُمَّتَكَ لَا تُطِيقُ ذَلِكَ، فَرَاجَعْتُهُ، فَقَالَ: هِيَ خَمْسٌ وَهِيَ خَمْسُونَ، لَا يُبَدَّلُ الْقَوْلُ لَدَيَّ، فَرَجَعْتُ إِلَى مُوسَى فَقَالَ: ارْجِعْ إِلَى رَبِّكَ، فَقُلْتُ اسْتَحْيَيْتُ مِنْ رَبِّي، ثُمَّ انْطَلَقَ بِي حَتَّى انْتَهَى بِي إِلَى سِدْرَةِ الْمُنْتَهَى وَغَشِيَهَا أَلْوَانٌ مَا أَدْرِي مَا هِيَ، ثُمَّ أُدْخِلْتُ الْجَنَّةَ فَإِذَا فِيهَا حَبَايِلُ اللُّؤْلُؤِ وَإِذَا تُرَابُهَا الْمِسْكُ". (ق,ن,جه)', 'അനസുബ്നുമാലിക്(റ): നബി(സ) പറഞ്ഞതായി അബൂദർറ്(റ) പറയുന്നു: "ഞാൻ മക്കയിലായിരിക്കെ എന്റെ വീടിന്റെ മേൽക്കൂര നീക്കി ജിബ്രീൽ(അ) ഇറങ്ങി വന്നു. എന്റെ നെഞ്ചു പിളർത്തി അത് സംസം വെള്ളം കൊണ്ടു കഴുകി. വിജ്ഞാനവും ഈമാനും നിറച്ച സ്വർണ്ണപ്പാത്രം കൊണ്ടുവന്നു. പിന്നെ അതെന്റെ നെഞ്ചിൽ നിക്ഷേപിച്ച് അതിനെ ചേർത്തുവെച്ചു. പിന്നെ എന്റെ കൈപിടിച്ച് ഒന്നാം ആകാശത്തേക്ക് ഉയർത്തി. ഒന്നാം ആകാശത്തിലെത്തിയപ്പോൾ ജിബ്രീൽ(അ) അതിന്റെ കാവൽക്കാരോടു പറഞ്ഞു: തുറക്കൂ! കാവൽക്കാരൻ ചോദിച്ചു: ഇതാരാണ്? ജിബ്രീൽ(അ) പറഞ്ഞു: ഇത് ജിബ്രീലാണ്. കാവൽക്കാരൻ: താങ്കളുടെ കൂടെ ആരെങ്കിലുമുണ്ടോ? ജിബ്രീൽ(അ) പറഞ്ഞു: എന്റെ കൂടെ മുഹമ്മദ്(സ) ഉണ്ട്. കാവൽക്കാരൻ: അദ്ദേഹം ക്ഷണിക്കപ്പെട്ടുവോ? ജിബ്രീൽ(അ) പറഞ്ഞു: അതെ. അങ്ങനെ കവാടം തുറന്നപ്പോൾ ഞങ്ങൾ ഒന്നാം ആകാശത്തേക്കു കയറി. അപ്പോൾ ഒരാൾ ഇരിക്കുന്നതു കണ്ടു. അദ്ദേഹത്തിന്റെ വലതുവശത്ത് കുറെ ആളുകളും ഇടതുവശത്ത് കുറെ ആളുകളും ഉണ്ട്. അദ്ദേഹം വലതുവശത്തേക്കു നോക്കുമ്പോൾ ചിരിക്കുകയും ഇടതുവശത്തേക്കു നോക്കുമ്പോൾ കരയുകയും ചെയ്യുന്നുണ്ടായിരുന്നു. അദ്ദേഹം പറഞ്ഞു: ''സദ്വൃത്തനായ നബിയേ, സദ്വൃത്തനായ മകനേ, സ്വാഗതം.'' ഞാൻ ജിബ്രീൽ(അ)മിനോട് ചോദിച്ചു: ഇതാരാണ്? ജിബ്രീൽ(അ) പറഞ്ഞു: ഇതാണ് ആദം(അ). അദ്ദേഹത്തിന്റെ ഇടത്തും വലത്തുമുള്ള ആളുകൾ അദ്ദേഹത്തിന്റെ സന്താന പരമ്പരയാണ്. വലതുഭാഗത്തുള്ളവർ സ്വർഗ്ഗ വാസികളും ഇടതു ഭാഗത്തുള്ളവർ നരക വാസികളുമാണ്. അതിനാൽ അദ്ദേഹത്തിന്റെ വലതുഭാഗത്തേക്ക് നോക്കിയപ്പോൾ ചിരിക്കുന്നു. ഇടതുഭാഗത്തേക്ക് നോക്കിയപ്പോൾ കരയുന്നു. അങ്ങനെ എന്നെയും കൊണ്ട് ജിബ്രീൽ(അ) രണ്ടാം ആകാശത്തേക്ക് പോയി. അതിന്റെ കാവൽക്കാരനോട് തുറക്കാൻ ആവശ്യപ്പെട്ടു. ഒന്നാമത്തെ കാവൽക്കാരന്റെ ചോദ്യങ്ങൾ ഇദ്ദേഹവും ആവർത്തിച്ചു. ശേഷം തുറന്നു. അനസ്(റ) പറയുന്നു: ആകാശങ്ങളിൽ ആദം(അ), ഇദ്രീസ്(അ), മൂസാ(അ), ഈസാ(അ), ഇബ്റാഹീം(അ) എന്നീ നബിമാരെ കണ്ടതായി നബി(സ) പറഞ്ഞു. അവരുടെ പദവി എപ്രകാരമെന്ന് വ്യക്തമാക്കിയില്ല. എന്നാൽ ആദം(അ)മിനെ ഒന്നാം ആകാശത്തിലും ഇബ്റാഹീം(അ)മിനെ ആറാം ആകാശത്തിലും കണ്ടതായി പറഞ്ഞു. അനസ്(റ) പറയുന്നു: ജിബ്രീൽ(അ) നബി(സ)യേയും കൊണ്ട് ഇദ്രീസി(അ)ന്റെ അടുത്തെത്തിയപ്പോൾ ഇദ്രീസ്(അ) പറഞ്ഞു: ''ഉത്തമനായ നബിയേ, ഉത്തമനായ സഹോദരാ, സ്വാഗതം!'' ജിബ്രീൽ(അ)മിനോട് ഇതാരാണെന്ന് ഞാനന്വേഷിച്ചപ്പോൾ ഇത് ഇദ്രീസ്(അ) ആണ് എന്ന് പറഞ്ഞു. "പിന്നെ ഞാൻ മൂസാ(അ)യുടെ അടുത്തെത്തിയപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ''ഉത്തമനായ നബിയേ, ഉത്തമനായ സഹോദരാ, സ്വാഗതം!'' ജിബ്രീൽ(അ)മിനോട് ഇതാരാണ് എന്നന്വേഷിച്ചപ്പോൾ ഇത് മൂസാ(അ)യാണ് എന്ന് പറഞ്ഞു. പിന്നെ ഞാൻ ഈസാ(അ)യുടെ അടുത്തെത്തിയപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ''ഉത്തമനായ നബിയേ, ഉത്തമനായ സഹോദരാ, സ്വാഗതം!'' ജിബ്രീൽ(അ)മിനോട് ഇതാരാണ് എന്നന്വേഷിച്ചപ്പോൾ ഇത് ഈസാ(അ)യാണ് എന്ന് പറഞ്ഞു. പിന്നെ ഇബ്റാഹീമി(അ)ന്റെ അടുത്തെത്തിയപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ''ഉത്തമനായ നബിയേ, ഉത്തമനായ മകനേ, സ്വാഗതം.'' ജിബ്രീൽ(അ)മിനോട് ഇതാരാണ് എന്നന്വേഷിച്ചപ്പോൾ ഇത് ഇബ്റാഹീം(അ) ആണ് എന്ന് പറഞ്ഞു." ഇബ്നുഅബ്ബാസ്(റ), അബൂഹബ്ബത്തുൽ അൻസ്വാരി(റ) എന്നിവർ പറയുന്നു: നബി(സ) പറഞ്ഞു: "പിന്നെ എന്നെയുമായി ജിബ്രീൽ(അ) നിരപ്പായ ഒരു സ്ഥലത്ത് എത്തിച്ചേർന്നു. അവിടെ പേനകളുടെ ചലന ശബ്ദം ഞാൻ കേൾക്കുന്നുണ്ടായിരുന്നു." അനസുബ്നു മാലിക്(റ) പറയുന്നു: നബി(സ) പറഞ്ഞു: "അപ്പോൾ പ്രതാപവാനായ അല്ലാഹു എന്റെ സമുദായത്തിന്ന് അമ്പത് നേരത്തെ നിസ്കാരം നിർബന്ധമാക്കി. അതുമായി ഞാൻ തിരിച്ചു മൂസാ(അ)യുടെ അടുത്തെത്തി. മൂസാ(അ) ചോദിച്ചു: ''താങ്കളുടെ സമുദായത്തിന് അല്ലാഹു എന്താണ് നിർബന്ധമാക്കിയത്?'' ഞാൻ പറഞ്ഞു: ''അമ്പത് നേരത്തെ നിസ്കാരം.'' മൂസാ(അ) പറഞ്ഞു: ''താങ്കൾ റബ്ബിന്റെ അടുത്തേക്ക് മടങ്ങുക. താങ്കളുടെ സമൂഹത്തിന് ഇത് അസാധ്യമാണ്.'' അങ്ങനെ ഞാൻ തിരിച്ചുചെന്നപ്പോൾ പകുതിയായി കുറച്ചുതന്നു. പിന്നെ ഞാൻ മൂസാ(അ)യുടെ അടുത്തെത്തി പകുതിയാക്കിക്കുറച്ചത് അറിയിച്ചു. മൂസാ(അ) പറഞ്ഞു: തിരിച്ചു ചെല്ലുക. അങ്ങയുടെ സമുദായത്തിന് ഇത്രയും അസാധ്യമാണ്.'' അങ്ങനെ തിരിച്ച് അല്ലാഹുവിന്റെ അടുത്തെത്തിയപ്പോൾ പിന്നെയും പകുതിയാക്കിക്കുറച്ചു. തിരിച്ചു വന്നപ്പോൾ മൂസാ(അ) വീണ്ടും പറഞ്ഞു: ''അങ്ങ് തിരിച്ചുചെല്ലുക. അങ്ങയുടെ സമുദായത്തിന് ഇതും അസാധ്യമാണ്.'' വീണ്ടും തിരിച്ചു ചെന്നു. അപ്പോൾ അല്ലാഹു പറഞ്ഞു: "അഞ്ച് നേരം നിർവ്വഹിക്കുക. അത് അമ്പതിനു തുല്യമാണ്. എന്റെ പക്കൽ വാക്കുകൾക്ക് യാതൊരു മാറ്റവുമില്ലതന്നെ." തുടർന്ന് ഞാൻ മൂസാ(അ)യുടെ അടുത്തെത്തിയപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ''താങ്കൾ താങ്കളുടെ രക്ഷിതാവിന്റെ അരികിൽ മടങ്ങിപ്പോകുക.'' ഞാൻ പറഞ്ഞു: ''ഇനിയും മടങ്ങിപ്പോകാൻ എനിക്ക് ലജ്ജയുണ്ട്.'' പിന്നെ ജിബ്രീൽ(അ) എന്നെയുമായി ''സിദ്റത്തുൽ മുൻതഹായിൽ'' എത്തി. പല നിറങ്ങളും കൊണ്ട് അതു പൊതിഞ്ഞിരുന്നു. അത് എന്താണെന്ന് എനിക്ക് അറിഞ്ഞുകൂടാ. തുടർന്ന് ഞാൻ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കപ്പെട്ടു. അവിടെ മുത്തുകളാൽ നിർമ്മിതമായ കയറുകൾ ഉണ്ടായിരുന്നു. അവിടത്തെ മണ്ണ് കസ്തൂരിയായിരുന്നു." (ബു,മു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 310, 312, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا أُسْرِيَ بِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ انْتُهِيَ بِهِ إِلَى سِدْرَةِ الْمُنْتَهَى، وَهِيَ فِي السَّمَاءِ السَّادِسَةِ، وَإِلَيْهَا يَنْتَهِي مَا عُرِجَ بِهِ مِنْ تَحْتِهَا، وَإِلَيْهَا يَنْتَهِي مَا أُهْبِطَ بِهِ مِنْ فَوْقِهَا حَتَّى يُقْبَضَ مِنْهَا، قَالَ: {إِذْ يَغْشَى السِّدْرَةَ مَا يَغْشَى} قَالَ: فَرَاشٌ مِنْ ذَهَبٍ، فَأُعْطِيَ ثَلَاثًا، الصَّلَوَاتُ الْخَمْسُ، وَخَوَاتِيمُ سُورَةِ الْبَقَرَةِ، وَيُغْفَرُ لِمَنْ مَاتَ مِنْ أُمَّتِهِ لَا يُشْرِكُ بِاللهِ شَيْئًا الْمُقْحِمَاتُ. (ن)', 'അബ്ദുല്ല(റ): നബി(സ) രാപ്രയാണം നടത്തിയപ്പോൾ അവിടത്തെ ''സിദ്റത്തുൽ മുൻതഹാ''വരെ കൊണ്ടുപോയി. അത് ആറാം ആകാശത്തിലാണ്. താഴെനിന്ന് കയറിപ്പോകുന്നതൊക്കെ അവസാനിക്കുന്നത് അവിടെയാണ്. അതിന്റെ മുകളിൽ നിന്ന് താഴോട്ട് വരുന്നതും അവിടെയാണ് എത്തുന്നത്. എന്നിട്ട് "അതിനെ മൂടുന്നതൊക്കെയും അതിനെ വലയം ചെയ്തപ്പോൾ" (അന്നജ്മ് 12) എന്ന ആയത്ത് ഓതി. നിവേദകൻ പറയുന്നു: അത് സ്വർണ്ണത്തിനാലുള്ള ഒരു വിരിപ്പാണ്. അവിടെവെച്ച് നബി(സ)ക്ക് മൂന്ന് കാര്യങ്ങൾ നൽകപ്പെട്ടു. അഞ്ചു നേരത്തെ നിസ്കാരം, സൂറത്തുൽ ബഖറയുടെ അവസാന ഭാഗങ്ങൾ, അല്ലാഹുവിൽ പങ്കു ചേർക്കാതെ മരിച്ചുപോകുന്നവർക്കു വൻപാപങ്ങൾ പൊറുക്കപ്പെടും. (ന)', 'عَبْدِ اللهِ', 'അബ്ദുല്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 312, 312, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ الصَّلَوَاتِ فُرِضَتْ بِمَكَّةَ، وَأَنَّ مَلَكَيْنِ أَتَيَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَهَبَا بِهِ إِلَى زَمْزَمَ، فَشَقَّا بَطْنَهُ وَأَخْرَجَا حَشْوَهُ فِي طَسْتٍ مِنْ ذَهَبٍ، فَغَسَلَاهُ بِمَاءِ زَمْزَمَ، ثُمَّ كَبَسَا جَوْفَهُ حِكْمَةً وَعِلْمًا. (ن)', 'അനസുബ്നു മാലിക്(റ): നിസ്കാരങ്ങൾ നിർബന്ധമാക്കപ്പെട്ടത് മക്കയിൽ വെച്ചാണ്. രണ്ട് മലക്കുകൾ നബി(സ)യുടെ സമീപം വരികയും നബി(സ)യെ സംസമിന്റെ അടുത്ത് കൊണ്ടുപോയി വയർ പിളർത്തി ഉള്ളിലുള്ളത് സ്വർണ്ണത്തിന്റെ ഒരു പാത്രത്തിൽ പുറത്തെടുക്കുകയും പിന്നെ സംസം വെള്ളം കൊണ്ട് അത് കഴുകുകയും വിജ്ഞാനം, ഹിക്മത്ത് എന്നിവ അതിൽ നിറക്കുകയും ചെയ്തു. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 312, 312, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: فَرَضَ اللهُ عَزَّ وَجَلَّ الصَّلَاةَ عَلَى رَسُولِهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَوَّلَ مَا فَرَضَهَا رَكْعَتَيْنِ رَكْعَتَيْنِ، ثُمَّ أُتِمَّتْ فِي الْحَضَرِ أَرْبَعًا، وَأُقِرَّتْ صَلَاةُ السَّفَرِ عَلَى الْفَرِيضَةِ الْأُولَى. (ن)', 'ആഇശ(റ): പ്രതാപവാനായ അല്ലാഹു അവന്റെ ദൂതന് നിസ്കാരം നിർബന്ധമാക്കി. ആദ്യം അത് ഈരണ്ട് റക്അത്തുകളായിരുന്നു. പിന്നീട് നാട്ടിൽ വെച്ചുള്ള നിസ്കാരം നാലായി പൂർത്തീകരിച്ചു. ആദ്യമായി നിർബന്ധമാക്കപ്പെട്ട ഈരണ്ട് റക്അത്ത് യാത്രയിലെ നിസ്കാരമാക്കി സ്ഥിരപ്പെടുത്തി. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 312, 312, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: فُرِضَتِ الصَّلَاةُ عَلَى لِسَانِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْحَضَرِ أَرْبَعًا، وَفِي السَّفَرِ رَكْعَتَيْنِ، وَفِي الْخَوْفِ رَكْعَةً. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): പ്രവാചകർ(സ)യുടെ വാക്കിലൂടെ നിസ്കാരം നിർബന്ധമാക്കപ്പെട്ടത് നാട്ടിലുള്ളവർക്ക് നാലും, യാത്രയിൽ രണ്ടും, ഭയത്തിന്റെ അവസരത്തിൽ ഒന്നും റക്അത്തുകളാണ്. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 312, 312, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أُمَيَّةَ بْنِ عَبْدِ اللهِ بْنِ خَالِدِ بْنِ أَسِيدٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ قَالَ لِابْنِ عُمَرَ: كَيْفَ تَقْصُرُ الصَّلَاةَ؟ وَإِنَّمَا قَالَ اللهُ عَزَّ وَجَلَّ: {لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَقْصُرُوا مِنَ الصَّلَاةِ إِنْ خِفْتُمْ} فَقَالَ ابْنُ عُمَرَ: يَا ابْنَ أَخِي، إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَتَانَا وَنَحْنُ ضُلَّالٌ فَعَلَّمَنَا، فَكَانَ فِيمَا عَلَّمَنَا "أَنَّ اللهَ عَزَّ وَجَلَّ أَمَرَنَا أَنْ نُصَلِّيَ رَكْعَتَيْنِ فِي السَّفَرِ". (ن)', 'ഉമയ്യത്തുബ്നു അബ്ദില്ലാഹിബ്നു ഖാലിദിബ്നി അസീദ്(റ): അദ്ദേഹം ഇബ്നുഉമർ(റ)വിനോട് ചോദിച്ചു: (യാത്രയിൽ) നിസ്കാരം എങ്ങനെ ചുരുക്കി നിർവ്വഹിക്കാൻ കഴിയും?; "നിങ്ങൾ ഭീതിയിലായിരിക്കെ നിസ്കാരം ചുരുക്കി നിർവഹിക്കുന്നതിൽ നിങ്ങൾക്ക് കുറ്റമില്ല." (അന്നിസാഅ്:11) എന്ന് അല്ലാഹു പറഞ്ഞിട്ടുണ്ടല്ലോ. അപ്പോൾ ഇബ്നുഉമർ(റ) പറഞ്ഞു: സഹോദരപുത്രാ! ഞങ്ങൾ വഴി പിഴച്ചവരായിരിക്കെ നബി(സ) വരികയും ഞങ്ങളെ പഠിപ്പിക്കുകയും ചെയ്തു. അങ്ങനെ പഠിപ്പിച്ച കാര്യത്തിൽപ്പെട്ടതാണ് "യാത്രയിലായിരിക്കുമ്പോൾ രണ്ടു റക്അത്ത് നിസ്കരിക്കാൻ അല്ലാഹു നമ്മോട് കൽപിച്ചിരിക്കുന്നു"വെന്നത്. (ന)', 'أُمَيَّةَ بْنِ عَبْدِ اللهِ بْنِ خَالِدِ بْنِ أَسِيدٍ', 'ഉമയ്യത്തുബ്നു അബ്ദില്ലാഹിബ്നു ഖാലിദിബ്നി അസീദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 313, 313, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: فَرَضَ اللهُ الصَّلَاةَ حِينَ فَرَضَهَا رَكْعَتَيْنِ رَكْعَتَيْنِ فِي الْحَضَرِ وَالسَّفَرِ، فَأُقِرَّتْ صَلَاةُ السَّفَرِ، وَزِيدَ فِي صَلَاةِ الْحَضَرِ. (خ)', 'ആഇശ(റ): അല്ലാഹു നിസ്കാരം നിർബന്ധമാക്കിയപ്പോൾ അത് നാട്ടിലായിരിക്കുമ്പോഴും, യാത്രയിലായിരിക്കുമ്പോഴും രണ്ട് റക്അത്താണ് നിർവ്വഹിക്കേണ്ടതെന്ന് നിയമമാക്കി. പിന്നീട് യാത്രയിലെ നിസ്കാരം അപ്രകാരം (രണ്ടു റക്അത്തായി) തന്നെ സ്ഥിരപ്പെടുത്തുകയും നാട്ടിൽ വെച്ചുള്ള നിസ്കാരം (നിസ്കാരത്തിലെ റക്അത്തുകളുടെ എണ്ണം) വർദ്ധിപ്പിക്കുകയും ചെയ്തു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 313, 313, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَرَأَيْتُمْ لَوْ أَنَّ نَهْرًا بِبَابِ أَحَدِكُمْ يَغْتَسِلُ مِنْهُ كُلَّ يَوْمٍ خَمْسَ مَرَّاتٍ، هَلْ يَبْقَى مِنْ دَرَنِهِ شَيْءٌ؟" قَالُوا: لَا يَبْقَى مِنْ دَرَنِهِ شَيْءٌ، قَالَ: "فَذَلِكَ مَثَلُ الصَّلَوَاتِ الْخَمْسِ، يَمْحُو اللهُ بِهِنَّ الْخَطَايَا". (م,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാളുടെ വീടിനു മുന്നിൽ ഒരു അരുവി ഉണ്ടായിരിക്കെ ദിവസവും അഞ്ച് നേരം അതിൽനിന്ന് അവൻ കുളിക്കുന്നു. അയാളിൽ എന്തെങ്കിലും അഴുക്ക് അവശേഷിക്കുമോ? നിങ്ങളുടെ അഭിപ്രായമെന്താണ്? അനുചരർ പറഞ്ഞു: അയാളിൽ ഒരു മാലിന്യവും അവശേഷിക്കില്ല. പ്രവാചകൻ(സ) പറഞ്ഞു: "അഞ്ച് നേരത്തെ നിസ്കാരത്തിന്റെ ഉപമ അപ്രകാരമാണ്. അതു മുഖേന അല്ലാഹു അവരുടെ തെറ്റുകൾ മായ്ച്ചു കളയുന്നു." (മു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 313, 313, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الْعَهْدَ الَّذِي بَيْنَنَا وَبَيْنَهُمُ الصَّلَاةُ، فَمَنْ تَرَكَهَا فَقَدْ كَفَرَ". (ن)', 'ബുറൈദ(റ): നബി(സ) പറഞ്ഞു: "നമ്മുടെയും അവരുടേയും (നിഷേധികൾ) ഇടയിലുള്ള വ്യവസ്ഥ നിസ്കാരമാണ്. ആർ അത് ഉപേക്ഷിച്ചുവോ അവൻ നിഷേധിയായി." (ന)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 313, 313, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَيْسَ بَيْنَ الْعَبْدِ وَبَيْنَ الْكُفْرِ إِلَّا تَرْكُ الصَّلَاةِ". (ن)', 'ജാബിർ(റ): നബി(സ) പറഞ്ഞു: "ഒരടിമയുടേയും സത്യനിഷേധത്തിന്റെയും ഇടയിൽ നിസ്കാരം ഉപേക്ഷിക്കലല്ലാതെ (വ്യത്യാസം) മറ്റൊന്നുമില്ല." (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 314, 314, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَلَا تُبَايِعُونَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟" فَرَدَّدَهَا ثَلَاثَ مَرَّاتٍ، فَقَدَّمْنَا أَيْدِيَنَا فَبَايَعْنَاهُ، فَقُلْنَا: يَا رَسُولَ اللهِ! قَدْ بَايَعْنَاكَ، فَعَلَامَ؟ قَالَ: "عَلَى أَنْ تَعْبُدُوا اللهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا، وَالصَّلَوَاتِ الْخَمْسِ" وَأَسَرَّ كَلِمَةً خَفِيَّةً، "أَنْ لَا تَسْأَلُوا النَّاسَ شَيْئًا". (ن)', 'ഔഫുബ്നുമാലികിൽ അശ്ജഈ(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ അടുത്തായിരിക്കെ അവിടുന്ന് ഇപ്രകാരം പറഞ്ഞു: "നിങ്ങൾ അല്ലാഹുവിന്റെ ദൂതനുമായി ഉടമ്പടി ചെയ്യുന്നില്ലേ?" മൂന്നുപ്രാവശ്യം നബി(സ) അപ്രകാരം ആവർത്തിച്ചു. ഞങ്ങൾ കൈനീട്ടി നബി(സ)യോട് ബൈഅത്ത് ചെയ്തു, നബിയേ! ഞങ്ങൾ എന്തു കാര്യത്തിലാണ് താങ്കളുമായി ഉടമ്പടി ചെയ്യേണ്ടത്?. നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിനെ ആരാധിക്കുമെന്നും അവനിൽ യാതൊന്നിനെയും പങ്കുചേർക്കുകയില്ല എന്നും പിന്നെ അഞ്ച് നേരത്തെ നിസ്കാരത്തിന്റെ കാര്യത്തിലും." ശബ്ദം താഴ്ത്തി കൊണ്ട് നബി(സ) മറ്റൊരു വാക്യം കൂടി പറഞ്ഞു. "നിങ്ങൾ ജനങ്ങളോട് ഒന്നും ചോദിക്കുകയില്ല എന്നും (നിങ്ങൾ കരാർ ചെയ്യുക)." (ന)', 'عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ', 'ഔഫുബ്നുമാലികിൽ അശ്ജഈ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 314, 314, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ أَوَّلَ مَا يُحَاسَبُ بِهِ الْعَبْدُ بِصَلَاتِهِ، فَإِنْ صَلَحَتْ فَقَدْ أَفْلَحَ وَأَنْجَحَ، وَإِنْ فَسَدَتْ فَقَدْ خَابَ وَ خَسِرَ، فَإِنِ انْتَقَصَ مِنْ فَرِيضَتِهِ شَيْءٌ، قَالَ: انْظُرُوا هَلْ لِعَبْدِي مِنْ تَطَوُّعٍ، فَيُكَمَّلَ بِهِ مَا نَقَصَ مِنَ الْفَرِيضَةِ ثُمَّ يَكُونُ سَائِرُ عَمَلِهِ عَلَى نَحْوِ ذَلِكَ". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു. "ഒരടിമ ഒന്നാമതായി ചോദ്യം ചെയ്യപ്പെടുന്നത് അവന്റെ നിസ്കാരത്തെക്കുറിച്ചായിരിക്കും. അതു നന്നായാൽ അവൻ വിജയിക്കുകയും രക്ഷപ്പെടുകയും ചെയ്തു. അത് മോശമായാൽ അവൻ പരാജിതനും നഷ്ടക്കാരനുമായി. അവന്റെ നിർബന്ധ കർമ്മത്തിൽ വല്ല ന്യൂനതയും സംഭവിച്ചാൽ അല്ലാഹു പറയും: എന്റെ അടിമ വല്ല ഐച്ഛിക കർമ്മവും ചെയ്തിട്ടുണ്ടോ എന്ന് നോക്കൂ? അതുമുഖേന നിർബന്ധ കർമ്മത്തിന്റെ ന്യൂനത പരിഹരിക്കും. അവന്റെ മറ്റു കർമ്മങ്ങളും ഇപ്രകാരം തന്നെയായിരിക്കും." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 314, 314, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ أَبِي أَيُّوبَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا قَالَ: يَا رَسُولَ اللهِ! أَخْبِرْنِي بِعَمَلٍ يُدْخِلُنِي الْجَنَّةَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "تَعْبُدُ اللهَ وَلَا تُشْرِكُ بِهِ شَيْئًا، وَتُقِيمُ الصَّلَاةَ، وَتُؤْتِي الزَّكَاةَ، وَتَصِلُ الرَّحِمَ، ذَرْهَا" كَأَنَّهُ كَانَ عَلَى رَاحِلَتِهِ. (ن)', 'അബൂഅയ്യൂബ്(റ): ഒരാൾ നബി(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ! എന്നെ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കുന്ന ഒരു കർമ്മം എനിക്കറിയിച്ചു തന്നാലും. നബി(സ) പറഞ്ഞു: "നീ അല്ലാഹുവിനെ ആരാധിക്കുക (ഇബാദത്ത് ചെയ്യുക), അവനിൽ യാതൊന്നും പങ്കുചേർക്കാതിരിക്കുക, നിസ്കാരം നിലനിർത്തുക, സകാത്ത് നൽകുക, കുടുംബ ബന്ധം ചേർക്കുക." (തുടർന്ന് നബി(സ) പറഞ്ഞു) "അതിനെ വിട്ടേക്കുക". അവിടുന്ന് സ്വന്തം വാഹനത്തിലായിരുന്നുവെന്ന് എനിക്ക് തോന്നി. (ന)', 'أَبِي أَيُّوبَ', 'അബൂഅയ്യൂബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 314, 315, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ طَلْحَةَ بْنِ عُبَيْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ أَهْلِ نَجْدٍ ثَائِرُ الرَّأْسِ، يُسْمَعُ دَوِيُّ صَوْتِهِ وَ لَا يُفْقَهُ مَا يَقُولُ حَتَّى دَنَا، فَإِذَا هُوَ يَسْأَلُ عَنِ الْإِسْلَامِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خَمْسُ صَلَوَاتٍ فِي الْيَوْمِ وَ اللَّيْلَةِ". قَالَ: هَلْ عَلَيَّ غَيْرُهُنَّ؟ قَالَ: "لَا، إِلَّا أَنْ تَطَّوَّعَ". قَالَ: وَذَكَرَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صِيَامَ شَهْرِ رَمَضَانَ قَالَ: هَلْ عَلَيَّ غَيْرُهُ؟ قَالَ: "لَا، إِلَّا أَنْ تَطَّوَّعَ". قَالَ: وَذَكَرَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الصَّدَقَةَ، قَالَ: هَلْ عَلَيَّ غَيْرُهَا؟ قَالَ: "لَا، إِلَّا أَنْ تَطَّوَّعَ". فَأَدْبَرَ الرَّجُلُ وَهُوَ يَقُولُ: وَاللهِ لَا أَزِيدُ عَلَى هَذَا وَلَا أَنْقُصُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَفْلَحَ إِنْ صَدَقَ". (ق,د,ن)', 'ത്വൽഹതുബ്നു ഉബൈദില്ല(റ): നബി(സ)യുടെ അടുത്ത് നജ്ദിൽ നിന്നും ഒരാൾ വന്നു. അയാളുടെ മുടി പാറിപ്പറക്കുകയും ശബ്ദത്തിന്റെ മുഴക്കം കേൾക്കുകയും ചെയ്തിരുന്നു. അദ്ദേഹം പറയുന്നത് വ്യക്തമായിരുന്നില്ല. അങ്ങനെ അയാൾ നബി(സ)യുടെ അടുത്തെത്തിയപ്പോൾ ഇസ്ലാമിനെക്കുറിച്ച് ചോദിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "രാത്രിയും പകലുമായി അഞ്ച് നേരത്തെ നിസ്കാരം (നീ നിർവ്വഹിക്കുക)". അയാൾ ചോദിച്ചു: അതല്ലാതെ മറ്റെന്തെങ്കിലും ഞാൻ (നിർബന്ധമായും) ചെയ്യേണ്ടതുണ്ടോ? നബി(സ) പറഞ്ഞു: "ഇല്ല, ഐച്ഛികമായി നീ (വല്ലതും) ചെയ്യുന്നുവെങ്കിലല്ലാതെ." നബി(സ) അയാളെ റമദാനിലെ നോമ്പിനെക്കുറിച്ച് ഓർമ്മിപ്പിച്ചപ്പോൾ അയാൾ ചോദിച്ചു: അതല്ലാതെ മറ്റെന്തെങ്കിലും ഞാൻ നിർവ്വഹിക്കേണ്ടതുണ്ടോ? പ്രവാചകൻ(സ): "ഇല്ല, ഐച്ഛികമായി നീ (വല്ലതും) ചെയ്യുന്നുവെങ്കിലല്ലാതെ". നബി(സ) അയാളെ ദാനത്തെക്കുറിച്ചു ഓർമ്മിപ്പിച്ചു. അയാൾ: അതല്ലാതെ മറ്റെന്തെങ്കിലുമുണ്ടോ? നബി(സ): "ഇല്ല, ഐച്ഛികമായി നീ (വല്ലതും) ചെയ്യുന്നുവെങ്കിലല്ലാതെ". ആ മനുഷ്യൻ ഇപ്രകാരം പറഞ്ഞ് തിരിച്ചുപോയി: "അല്ലാഹുവാണ! ഞാൻ ഇതിൽ നിന്നും ഒന്നും കൂട്ടുകയോ കുറക്കുകയോ ഇല്ല." അപ്പോൾ നബി(സ) പറഞ്ഞു: "അയാൾ സത്യമാണ് പറഞ്ഞതെങ്കിൽ വിജയിച്ചു". (ബു,മു,ദ,ന)', 'طَلْحَةَ بْنِ عُبَيْدِ اللهِ', 'ത്വൽഹതുബ്നു ഉബൈദില്ല(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 315, 315, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "خَمْسُ صَلَوَاتٍ افْتَرَضَهُنَّ اللهُ عَلَى عِبَادِهِ، فَمَنْ جَاءَ بِهِنَّ لَمْ يَنْتَقِصْ مِنْهُنَّ شَيْئًا اسْتِخْفَافًا بِحَقِّهِنَّ، فَإِنَّ اللهَ جَاعِلٌ لَهُ يَوْمَ الْقِيَامَةِ عَهْدًا أَنْ يُدْخِلَهُ الْجَنَّةَ، وَمَنْ جَاءَ بِهِنَّ قَدِ انْتَقَصَ مِنْهُنَّ شَيْئًا اسْتِخْفَافًا بِحَقِّهِنَّ لَمْ يَكُنْ لَهُ عِنْدَ اللهِ عَهْدٌ، إِنْ شَاءَ عَذَّبَهُ، وَإِنْ شَاءَ غَفَرَ لَهُ". (د,ن,جه)', 'ഉബാദതുബ്നു സ്വാമിത്(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "അഞ്ച് നേരത്തെ നിസ്കാരം അല്ലാഹു അവന്റെ അടിമകൾക്കു നിർബന്ധമാക്കി. അതിൽ യാതൊരു ന്യൂനതയും വരുത്താതെ, നിർവഹണത്തിൽ വീഴ്ച വരുത്താതെ നിർവഹിച്ചാൽ അന്ത്യദിനത്തിൽ അവന് സ്വർഗ്ഗം നൽകാമെന്ന് അല്ലാഹു കരാർ ചെയ്യുന്നു. അവയെ ലാഘവപൂർവം പരിഗണിച്ച് നിർവഹണത്തിൽ വീഴ്ചവരുത്തി ന്യൂനതകളോടെയാണ് അവനത് നിർവഹിക്കുന്നതെങ്കിൽ അവനുമായി അല്ലാഹുവിന് യാതൊരു കരാറുമില്ല. അവനുദ്ദേശിച്ചാൽ ശിക്ഷിക്കും, ഉദ്ദേശിച്ചാൽ പൊറുത്തു കൊടുക്കും". (ദ,ന,ജ)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നു സ്വാമിത്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 315, 315, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ أَبِي قَتَادَةَ بْنِ رِبْعِيٍّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "قَالَ اللهُ عَزَّ وَجَلَّ: افْتَرَضْتُ عَلَى أُمَّتِكَ خَمْسَ صَلَوَاتٍ، وَعَهِدْتُ عِنْدِي عَهْدًا أَنَّهُ مَنْ حَافَظَ عَلَيْهِنَّ لِوَقْتِهِنَّ أَدْخَلْتُهُ الْجَنَّةَ، وَمَنْ لَمْ يُحَافِظْ عَلَيْهِنَّ فَلَا عَهْدَ لَهُ عِنْدِي". (د,جه)', 'അബൂഖതാദ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹു പറഞ്ഞു: താങ്കളുടെ സമുദായത്തിന് അഞ്ചു നേരത്തെ നിസ്കാരം ഞാൻ നിർബന്ധമാക്കിയിരിക്കുന്നു. അവ അവയുടെ സമയങ്ങളിൽ നിർവഹിച്ചാൽ അവനെ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കുമെന്ന് ഞാൻ കരാറെടുത്തിരിക്കുന്നു, ആർ യഥാവിധി നിർവ്വഹിക്കുന്നില്ലയോ അവന് എന്റെ വാഗ്ദാനം ബാധകമല്ല". (ദ,ജ)', 'أَبِي قَتَادَةَ بْنِ رِبْعِيٍّ', 'അബൂഖതാദ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 316, 316, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=16 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
